export function SuccessState({
  message = "{{message}}",
  accent = "{{accent}}",
  force = {{force}},
  radius = {{radius}},
}) {
  return (
    <div style={{ width: 300, boxSizing: "border-box", font: "14px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12 }}>
      <button type="button" style={{ font: "700 14px system-ui, sans-serif", padding: "10px 20px", borderRadius: 8, border: "none", background: "#241430", color: "#FAF7F2", cursor: "pointer", marginBottom: 10 }}>Pay now</button>
      {force && (
        <div role="status" style={{ display: "flex", alignItems: "flex-start", gap: 8, padding: "12px 14px", borderRadius: radius, background: `color-mix(in srgb, ${accent} 25%, #FAF7F2)`, border: `1.5px solid color-mix(in srgb, ${accent} 55%, transparent)`, color: `color-mix(in srgb, ${accent} 65%, #241430)`, fontWeight: 600, fontSize: 13 }}>
          <svg width="18" height="18" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9" fill="none" stroke="currentColor" strokeWidth="2" /><path d="m8 12.5 2.5 2.5L16 9" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" fill="none" /></svg>
          <span>{message}</span>
        </div>
      )}
    </div>
  );
}
